      DATA (CASES(I,38),I=4,6) / 1.000000000000000D+00,0.000000000000000D+00,0.000000000000000D+00 /
      DATA (CASES(I,39),I=1,3) / 5.000000000000000D+00,5.000000000000000D+00,1.000000000000000D+00 /
