      DATA (CASES(I,40),I=4,6) / 1.000000000000000D-09,0.000000000000000D+00,0.000000000000000D+00 /
      DATA (CASES(I,41),I=1,3) / 2.000000000000000D+00,1.000000000000000D+00,3.000000000000000D+00 /
      DATA (CASES(I,41),I=4,6) / 1.000000000000000D-09,0.000000000000000D+00,0.000000000000000D+00 /
      DIMENSION E(6), PS(3), AN(3,3), R(3,3), OUT(6), PS2(3), EE(6)
      E0 = PROPS(1)
      ANU = PROPS(2)
      G = E0/(2.D0*(1.D0+ANU))
      XL = E0*ANU/((1.D0+ANU)*(1.D0-2.D0*ANU))
      DO I=1,NTENS
        DO J=1,NTENS
          DDSDDE(I,J)=0.D0
        END DO
      END DO
      DO I=1,NDI
        DO J=1,NDI
          DDSDDE(I,J)=XL
        END DO
        DDSDDE(I,I)=XL+2.D0*G
      END DO
      DO I=NDI+1,NTENS
        DDSDDE(I,I)=G
      END DO
      DO I=1,NTENS
        DO J=1,NTENS
          STRESS(I)=STRESS(I)+DDSDDE(I,J)*DSTRAN(J)
        END DO
      END DO
      DO I=1,NTENS
        EE(I)=STRAN(I)+DSTRAN(I)
      END DO
      CALL GETENV('UTILPROBE',PATHV)
      OPEN(UNIT=97,FILE=PATHV,POSITION='APPEND')
      WRITE(97,'(A,I4,A,I4)') 'CALL KINC',KINC,' NOEL',NOEL
      WRITE(97,'(A,6(1X,ES25.16))') 'STRESS',(STRESS(I),I=1,NTENS)
      WRITE(97,'(A,6(1X,ES25.16))') 'STRAIN',(EE(I),I=1,NTENS)
      CALL SPRIND(STRESS,PS,AN,1,NDI,NSHR)
      WRITE(97,'(A,3(1X,ES25.16))') 'SPRIND_PS',(PS(I),I=1,3)
      WRITE(97,'(A,9(1X,ES25.16))') 'SPRIND_AN',((AN(I,J),J=1,3),I=1,3)
      CALL SPRIND(EE,PS,AN,2,NDI,NSHR)
      WRITE(97,'(A,3(1X,ES25.16))') 'SPRINDE_PS',(PS(I),I=1,3)
      WRITE(97,'(A,9(1X,ES25.16))') 'SPRINDE_AN',((AN(I,J),J=1,3),I=1,3)
      CALL SPRINC(STRESS,PS2,1,NDI,NSHR)
      WRITE(97,'(A,3(1X,ES25.16))') 'SPRINC_PS',(PS2(I),I=1,3)
      CALL SPRINC(EE,PS2,2,NDI,NSHR)
      WRITE(97,'(A,3(1X,ES25.16))') 'SPRINCE_PS',(PS2(I),I=1,3)
      CALL SINV(STRESS,SI1,SI2,NDI,NSHR)
      WRITE(97,'(A,2(1X,ES25.16))') 'SINV',SI1,SI2
      CALL SINV(EE,SI1,SI2,NDI,NSHR)
      WRITE(97,'(A,2(1X,ES25.16))') 'SINV_ON_STRAIN',SI1,SI2
C     rotation about z by 30 deg composed with x by 20 deg
      C1=COS(0.5235987755982988D0); S1=SIN(0.5235987755982988D0)
      C2=COS(0.3490658503988659D0); S2=SIN(0.3490658503988659D0)
      R(1,1)=C1;   R(1,2)=-S1*C2; R(1,3)=S1*S2
      R(2,1)=S1;   R(2,2)=C1*C2;  R(2,3)=-C1*S2
      R(3,1)=0.D0; R(3,2)=S2;     R(3,3)=C2
      WRITE(97,'(A,9(1X,ES25.16))') 'R',((R(I,J),J=1,3),I=1,3)
      CALL ROTSIG(STRESS,R,OUT,1,NDI,NSHR)
      WRITE(97,'(A,6(1X,ES25.16))') 'ROTSIG_STRESS',(OUT(I),I=1,NTENS)
      CALL ROTSIG(EE,R,OUT,2,NDI,NSHR)
      WRITE(97,'(A,6(1X,ES25.16))') 'ROTSIG_STRAIN',(OUT(I),I=1,NTENS)
      CLOSE(97)

      IF (KINC.EQ.1 .AND. NOEL.EQ.1 .AND. NPT.EQ.1 .AND. TIME(2).EQ.0.D0) THEN
      OPEN(UNIT=98,FILE=PATHV(1:LEN_TRIM(PATHV))//'.cases',POSITION='APPEND')
      DO IC=1,41
        DO I=1,6
          EE(I)=CASES(I,IC)
        IF (NDI.EQ.2) THEN
          EE(3)=CASES(4,IC)
        END IF
        END DO
        CALL SPRIND(EE,PS,AN,1,NDI,NSHR)
        CALL SPRINC(EE,PS2,1,NDI,NSHR)
        CALL SINV(EE,SI1,SI2,NDI,NSHR)
        WRITE(98,'(A,I3,6(1X,ES25.16),A,3(1X,ES25.16),A,3(1X,ES25.16),A,2(1X,ES25.16),A,9(1X,ES25.16))')
     1   'C',IC,(EE(I),I=1,6),' PS',(PS(I),I=1,3),' PC',(PS2(I),I=1,3),
     2   ' SINV',SI1,SI2,' AN',((AN(I,J),J=1,3),I=1,3)
      END DO
      CLOSE(98)
      END IF
      RETURN
      END
